set -euo pipefail
: "${OUT:?fresh directory}" "${SERVER:?pinned server}" "${WEIGHTS:?pinned 72B shards}";B=benchmarks/quant_serving;A=$B/fifo72;D=$A/live;mkdir -p .runtime;REF=reports/qwen72b/assignment;export PYTHONPATH="$PWD/$A:$PWD/$B" PYTHONDONTWRITEBYTECODE=1
exec 9>.runtime/gpu-execution.lock;flock -x 9;test -z "$(nvidia-smi --query-compute-apps=pid --format=csv,noheader)";mkdir "$OUT";python3 -B - "$OUT/admission.json" <<'ADMIT'
import json,shutil,sys
from pathlib import Path
avail=int(next(s.split()[1] for s in Path('/proc/meminfo').read_text().splitlines() if s.startswith('MemAvailable:')))*1024;disk=shutil.disk_usage('.').free;ok=avail>=64*2**30 and disk>=2*2**30
Path(sys.argv[1]).write_text(json.dumps(dict(admitted=ok,required=64*2**30,available=avail,free_disk=disk,required_disk=2*2**30))+'\n');sys.exit(0 if ok else 75)
ADMIT
python3 -B "$B/verify_lock.py" "$B/qwen72b-q4km.lock.json" "$WEIGHTS" > "$OUT/checkpoint.json";cmp -s "$REF/checkpoint.json" "$OUT/checkpoint.json";PORT=$(python3 -c 'import socket;s=socket.socket();s.bind(("127.0.0.1",0));print(s.getsockname()[1]);s.close()')
"$SERVER" --model "$WEIGHTS/qwen2.5-72b-instruct-q4_k_m-00001-of-00012.gguf" --host 127.0.0.1 --port "$PORT" --parallel 2 --ctx-size 8192 --batch-size 512 --ubatch-size 128 --gpu-layers all --flash-attn on --cache-ram 0 --no-webui --no-context-shift > "$OUT/server.private.log" 2>&1 & pid=$!;watcher='';stop(){ if [[ -n "$watcher" ]];then kill -TERM "$watcher" 2>/dev/null||:;wait "$watcher" 2>/dev/null||:;fi;kill -TERM "$pid" 2>/dev/null||:;wait "$pid" 2>/dev/null||:; };trap stop EXIT;trap 'exit 143' TERM;trap 'exit 130' INT
python3 -B "$B/physical_guard.py" watch "$pid" "$SERVER" "$OUT/memory-guard.json" & watcher=$!;ready=0;for _ in $(seq 1 240);do kill -0 "$pid";if curl --noproxy '*' -fsS --max-time 3 "http://127.0.0.1:$PORT/health" 2>/dev/null|grep -q '"ok"';then ready=1;break;fi;sleep 3;done;[[ $ready == 1 ]];grep -E 'offloaded 81/81 layers to GPU' "$OUT/server.private.log";python3 -B "$B/runtime_receipt.py" --pid "$pid" --server "$SERVER" --log "$OUT/server.private.log" --layers 81 --slots 2 --ubatch 128 > "$OUT/runtime.json";cmp -s "$REF/runtime.json" "$OUT/runtime.json";SPARKFUSE_EOG_IDS=$(python3 -c 'import json,sys;print(json.dumps(json.load(open(sys.argv[1]))["eog_token_ids"]))' "$OUT/runtime.json");export SPARKFUSE_EOG_IDS
touch "$OUT/requests.started";python3 -Bu "$D/live72.py" "$PORT" "$REF" "$OUT/rows.json";touch "$OUT/requests.finished";wait "$watcher";watcher='';kill -0 "$pid";python3 -B "$B/physical_guard.py" check "$OUT/memory-guard.json";python3 -B "$D/live72_review.py" "$OUT" "$REF" > "$OUT/summary.partial";mv "$OUT/summary.partial" "$OUT/summary.json"
